        T_9x9.block(base+1, base+1, 2, 2) = T_local.topLeftCorner(2,2); // [theta_x; theta_y]
    }

    // Compute K_local (9x9) in plate-local coordinates using exact analytical formula for right triangle
    // Reference: NASTRAN KTRPLT verification, Bathe "Finite Element Procedures"
    // K_local = (D / (12 * area^2)) * M, where M is dimensionless 9x9 matrix
    const double coeff = D / (12.0 * area * area);

    // M matrix for triangle with vertices (0,0), (1,0), (0,1) — verified against NASTRAN
    Eigen::MatrixXd M(9, 9);
    M.setZero();
    // w-w block (top-left 3x3)
    M(0,0) = 4.0; M(0,3) = 2.0; M(0,6) = 2.0;
    M(3,0) = 2.0; M(3,3) = 4.0; M(3,6) = 2.0;
    M(6,0) = 2.0; M(6,3) = 2.0; M(6,6) = 4.0;
    // theta_x-theta_x block (rows 1,4,7; cols 1,4,7)
    M(1,1) = 4.0; M(1,4) = 2.0; M(1,7) = 2.0;
    M(4,1) = 2.0; M(4,4) = 4.0; M(4,7) = 2.0;
    M(7,1) = 2.0; M(7,4) = 2.0; M(7,7) = 4.0;
    // theta_y-theta_y block (rows 2,5,8; cols 2,5,8)
    M(2,2) = 4.0; M(2,5) = 2.0; M(2,8) = 2.0;
    M(5,2) = 2.0; M(5,5) = 4.0; M(5,8) = 2.0;
    M(8,2) = 2.0; M(8,5) = 2.0; M(8,8) = 4.0;
    // w-theta_x coupling (rows 0,3,6; cols 1,4,7) and symmetric
    M(0,1) = 2.0; M(0,4) = -1.0; M(0,7) = -1.0;
    M(3,1) = -1.0; M(3,4) = 2.0; M(3,7) = -1.0;
    M(6,1) = -1.0; M(6,4) = -1.0; M(6,7) = 2.0;
    M(1,0) = M(0,1); M(4,0) = M(0,4); M(7,0) = M(0,7);
    M(1,3) = M(3,1); M(4,3) = M(3,4); M(7,3) = M(3,7);
    M(1,6) = M(6,1); M(4,6) = M(6,4); M(7,6) = M(6,7);
    // w-theta_y coupling (rows 0,3,6; cols 2,5,8) and symmetric
    M(0,2) = 2.0; M(0,5) = -1.0; M(0,8) = -1.0;
    M(3,2) = -1.0; M(3,5) = 2.0; M(3,8) = -1.0;
    M(6,2) = -1.0; M(6,5) = -1.0; M(6,8) = 2.0;
    M(2,0) = M(0,2); M(5,0) = M(0,5); M(8,0) = M(0,8);
    M(2,3) = M(3,2); M(5,3) = M(3,5); M(8,3) = M(3,8);
    M(2,6) = M(6,2); M(5,6) = M(6,5); M(8,6) = M(6,8);
    // theta_x-theta_y coupling (rows 1,4,7; cols 2,5,8) and symmetric
    M(1,2) = 0.0; M(1,5) = 0.0; M(1,8) = 0.0;
    M(4,2) = 0.0; M(4,5) = 0.0; M(4,8) = 0.0;
    M(7,2) = 0.0; M(7,5) = 0.0; M(7,8) = 0.0;
    M(2,1) = M(1,2); M(5,1) = M(1,5); M(8,1) = M(1,8);
    M(2,4) = M(4,2); M(5,4) = M(4,5); M(8,4) = M(4,8);
    M(2,7) = M(7,2); M(5,7) = M(7,5); M(8,7) = M(7,8);

    // Add Poisson effect: coupling between kappa_x and kappa_y
    // D_mat = [[D, nu*D, 0], [nu*D, D, 0], [0,0,(1-nu)*D/2]]
    // So add nu*D * (terms) to off-diagonals
    // For simplicity, scale M by (1+nu) for diagonal and nu for off-diagonal w-w, theta-theta
    // But standard practice: multiply entire M by (1+nu) for isotropic coupling
    // We'll apply nu correction to w-w and theta-theta blocks
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            int r = i*3, c = j*3;
            if (i == j) {
                M(r,c) *= (1.0 + nu);
            } else {
                M(r,c) *= nu;
            }
        }
    }
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            int r = i*3+1, c = j*3+1; // theta_x-theta_x
            if (i == j) {
                M(r,c) *= (1.0 + nu);
            } else {
                M(r,c) *= nu;
            }
        }
    }
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            int r = i*3+2, c = j*3+2; // theta_y-theta_y
            if (i == j) {
                M(r,c) *= (1.0 + nu);
            } else {
                M(r,c) *= nu;
            }
        }
    }

    // K_local = coeff * M
    Eigen::MatrixXd K_local = coeff * M;

    // Transform to global coordinates: K_global = T_9x9^T * K_local * T_9x9
    Eigen::MatrixXd K = T_9x9.transpose() * K_local * T_9x9;

    // Now output as JSON
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 9; ++i) {
        std::cout << "[";
        for (int j = 0; j < 9; ++j) {
            std::cout << format_double(K(i,j));
            if (j < 8) std::cout << ",";
        }
        std::cout << "]";
        if (i < 8) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
